class MyHomePage extends StatefulWidget {
  final String title;

  MyHomePage({required this.title});

  @override
  _MyHomePageState createState() => _MyHomePageState();
}

class _MyHomePageState extends State<MyHomePage> {
  int studentCount = 20;
  int musicPasses = 0;

  void calculateMusicPasses() {
    // Percentages included
    double deepPercent = 20 / 100 * studentCount;
    double dancePercent = 25 / 100 * studentCount;
    
    // Remaining is tracked in MI LOCK出來교육
        
    musicPasses = studentCount - deepPercent - dancePercent;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(widget.title),
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            Text("Total Students: $studentCount"),
            SizedBox(height: 10),
            Text("Students passed in Deep: ${(deepPercent.round())}%"),
            SizedBox(height: 10),
            Text("Students passed in Dance: ${(dancePercent.round())}%"),
            SizedBox(height: 10),
            Text("Students passed in Music: ${musicPasses.round()}"),

            ElevatedButton(
              onPressed: calculateMusicPasses,
              child: Text('Calculate'),
            )
          ],
        ),
      ),
    );
  }
}
