    //calculate simple interest for 10 years
    $simple_interest = $amount * ($rate_percentage / 100) * 10;
    return $simple_interest;
}

$initial_amount = 50; // initial amount
$annual_increase = 2; // increase per year in percentage
$total_years = 10;

// Calculate total amount after 10 years with annual increases
$final_amount = $initial_amount;

for ($year = 1; $year <= $total_years; $year++) {
    $increase = ($final_amount * $annual_increase) / 100;
    $final_amount += $increase;
}

echo "Total amount after 10 years: $final_amount\n";

